import{_ as n,C as e,o as s,c as d,j as i,E as o,a as r,a2 as t}from"./chunks/framework.C21TwvGF.js";const P=JSON.parse(`{"title":"9-dars (Mentor). Relatsion ma’lumotlar bazalari va model tushunchasi (1-qism): Jadvallar, Primary Key, Foreign Key va munosabatlar","description":"","frontmatter":{"title":"9-dars (Mentor). Relatsion ma’lumotlar bazalari va model tushunchasi (1-qism): Jadvallar, Primary Key, Foreign Key va munosabatlar","layout":"doc","sidebar":false,"aside":false,"outline":false,"kind":"mentor_dars","dars":{"sinf":{"name":"9-sinf (BI)","link":"/mentor/9-sinf-bi/"},"week":{"n":3,"link":"/mentor/9-sinf-bi/hafta-03/"},"g":9,"title":"Relatsion ma’lumotlar bazalari va model tushunchasi (1-qism): Jadvallar, Primary Key, Foreign Key va munosabatlar","lead":"Dunyodagi barcha yirik axborot tizimlarining poydevori: ma'lumotlarni o'zaro bog'langan qat'iy jadvallar tizimida saqlash va boshqarish san'ati!","slide":"/slaydlar/9-sinf-bi/hafta-03/dars-3.html","test":"/slaydlar/9-sinf-bi/hafta-03/dars-3-test.html","student_link":"/9-sinf-bi/hafta-03/dars-3","tabs":[{"g":7,"link":"/mentor/9-sinf-bi/hafta-03/dars-1","current":false},{"g":8,"link":"/mentor/9-sinf-bi/hafta-03/dars-2","current":false},{"g":9,"link":"/mentor/9-sinf-bi/hafta-03/dars-3","current":true}],"prev":{"g":8,"title":"Pivot jadvallar (PivotTable) va ma'lumotlar vizualizatsiyasi","link":"/mentor/9-sinf-bi/hafta-03/dars-2"},"next":null}},"headers":[],"relativePath":"mentor/9-sinf-bi/hafta-03/dars-3.md","filePath":"mentor/9-sinf-bi/hafta-03/dars-3.md"}`),m={name:"mentor/9-sinf-bi/hafta-03/dars-3.md"},u={class:"blk"},h={id:"dars-rejasi",tabindex:"-1"},b={class:"blk"},y={id:"mentor-konspekti",tabindex:"-1"},g={class:"blk"},c={id:"amaliy-topshiriqlar-va-yechimlar",tabindex:"-1"},v={class:"blk"},k={id:"tezkor-nazorat-savollari",tabindex:"-1"},q={class:"blk"},f={id:"uyga-vazifa",tabindex:"-1"};function p(z,a,_,x,M,K){const l=e("Icon");return s(),d("div",null,[i("div",u,[i("h2",h,[o(l,{name:"file-text"}),a[0]||(a[0]=r(" Dars rejasi ",-1)),a[1]||(a[1]=i("a",{class:"header-anchor",href:"#dars-rejasi","aria-label":'Permalink to "<Icon name="file-text" /> Dars rejasi"'},"​",-1))]),a[2]||(a[2]=t("<ul><li><strong>Darsning maqsadi:</strong> O&#39;quvchilarga ma&#39;lumotlar bazasi (Database) va DBMS tushunchasi, Edgar F. Codd tomonidan asos solingan relatsion model tamoyillari, jadval (Table), satr (Row/Tuple), ustun (Column/Attribute) elementlari, birlamchi kalit (Primary Key), tashqi kalit (Foreign Key), ma&#39;lumotlar yaxlitligi (Data Integrity) hamda jadvallararo munosabatlar (1:1, 1:N, M:N) mohiyatini nazariy va amaliy jihatdan o&#39;rgatish.</li><li><strong>Kutiladigan natija:</strong> O&#39;quvchilar nima uchun Excel o&#39;rniga relatsion bazalar kerakligini tushunadi; Primary Key va Foreign Key farqini ajrata oladi; ikkita jadval o&#39;rtasidagi bog&#39;liqlikni aniqlaydi va munosabat turini (One-to-Many, Many-to-Many) to&#39;g&#39;ri modelley oladi.</li><li><strong>Vaqt taqsimoti:</strong><ul><li>O&#39;tgan mavzuni takrorlash (PivotTable va Excel xulosasi): 10 daqiqa</li><li>Yangi mavzu: Ma&#39;lumotlar bazasi, DBMS va Relatsion model: 20 daqiqa</li><li>Primary Key, Foreign Key va Ma&#39;lumotlar yaxlitligi: 25 daqiqa</li><li>Jadvallararo munosabatlar (1:1, 1:N, M:N) va model tuzish: 15 daqiqa</li><li>Mustahkamlash savollari va dars xulosasi: 10 daqiqa</li></ul></li></ul><hr>",2))]),i("div",b,[i("h2",y,[o(l,{name:"file-text"}),a[3]||(a[3]=r(" Mentor konspekti ",-1)),a[4]||(a[4]=i("a",{class:"header-anchor",href:"#mentor-konspekti","aria-label":'Permalink to "<Icon name="file-text" /> Mentor konspekti"'},"​",-1))]),a[5]||(a[5]=t('<h3 id="_1-ma-lumotlar-bazasi-database-va-dbms-tushunchasi" tabindex="-1">1. Ma&#39;lumotlar bazasi (Database) va DBMS tushunchasi <a class="header-anchor" href="#_1-ma-lumotlar-bazasi-database-va-dbms-tushunchasi" aria-label="Permalink to &quot;1. Ma&#39;lumotlar bazasi (Database) va DBMS tushunchasi&quot;">​</a></h3><ul><li><strong>Ma&#39;lumotlar bazasi (Database):</strong> Ma&#39;lumotlarni tartibli, tizimli, xavfsiz va bir-biriga bog&#39;langan holda saqlashga mo&#39;ljallangan maxsus elektron axborot omboridir.</li><li><strong>DBMS (Database Management System / MBBT):</strong> Ma&#39;lumotlar bazasini yaratish, boshqarish, o&#39;zgartirish, qidirish va xavfsizligini ta&#39;minlovchi dasturiy ta&#39;minot majmuasidir (masalan: PostgreSQL, MySQL, Microsoft SQL Server, Oracle).</li><li><strong>Nega Excel yetarli emas?</strong><ol><li><em>Hajm chegarasi:</em> Excel varag&#39;i faqat 1 048 576 qatorni sig&#39;dira oladi, DBMS esa milliardlab yozuvlarni boshqaradi.</li><li><em>Ko&#39;p foydalanuvchi rejimi:</em> Bir vaqtning o&#39;zida yuz minglab odamlar bazaga murojaat qilishi va xarid amalga oshirishi mumkin.</li><li><em>Ma&#39;lumot yaxlitligi va xavfsizlik:</em> Ruxsatsiz o&#39;zgartirishdan himoya va tranzaksion barqarorlik (ACID).</li></ol></li></ul><h3 id="_2-edgar-codd-va-relatsion-model-relational-model" tabindex="-1">2. Edgar Codd va Relatsion model (Relational Model) <a class="header-anchor" href="#_2-edgar-codd-va-relatsion-model-relational-model" aria-label="Permalink to &quot;2. Edgar Codd va Relatsion model (Relational Model)&quot;">​</a></h3><p>1970-yilda IBM olimi <strong>Edgar F. Codd</strong> tomonidan taklif qilingan. Markazida matematik to&#39;plamlar nazariyasi (set theory) yotadi. Asosiy tarkibiy elementlari:</p><ol><li><strong>Table (Jadval / Relation):</strong> Bir xil tuzilishga ega bo&#39;lgan subyektlar to&#39;plami (masalan, <code>Oquvchilar</code>, <code>Kurslar</code>, <code>Buyurtmalar</code>).</li><li><strong>Row (Satr / Tuple / Record):</strong> Jadvaldagi bitta aniq obyektning individual namunasi (masalan, Ali ismli o&#39;quvchi haqidagi ma&#39;lumotlar satri).</li><li><strong>Column (Ustun / Attribute / Field):</strong> Obyektning xususiyati yoki ko&#39;rsatkichi (masalan, <code>StudentID</code>, <code>Ism</code>, <code>TugilganSana</code>, <code>Telefon</code>).</li></ol><h3 id="_3-primary-key-birlamchi-kalit" tabindex="-1">3. Primary Key (Birlamchi kalit) <a class="header-anchor" href="#_3-primary-key-birlamchi-kalit" aria-label="Permalink to &quot;3. Primary Key (Birlamchi kalit)&quot;">​</a></h3><p>Jadvaldagi har bir satrni <strong>takrorlanmas va noyob (unique)</strong> tarzda aniqlovchi ustun yoki ustunlar to&#39;plami.</p><ul><li><strong>Xususiyatlari:</strong><ul><li>Hech qachon bo&#39;sh (<code>NULL</code>) bo&#39;lishi mumkin emas.</li><li>Qiymati takrorlanmaydi (dublikat bo&#39;lmaydi).</li><li>Jadvalda faqat 1 ta Primary Key bo&#39;ladi.</li></ul></li><li><strong>Misol:</strong> O&#39;zbekiston fuqarosining JShShIR (PINFL) raqami, talabaning <code>StudentID</code>, tovarning <code>Barcode</code> kodi.</li></ul><h3 id="_4-foreign-key-tashqi-kalit-va-ma-lumotlar-yaxlitligi" tabindex="-1">4. Foreign Key (Tashqi kalit) va Ma&#39;lumotlar yaxlitligi <a class="header-anchor" href="#_4-foreign-key-tashqi-kalit-va-ma-lumotlar-yaxlitligi" aria-label="Permalink to &quot;4. Foreign Key (Tashqi kalit) va Ma&#39;lumotlar yaxlitligi&quot;">​</a></h3><p>Boshqa jadvaldagi Primary Key ustuniga havola qiluvchi ustundir.</p><ul><li>Jadvallar o&#39;rtasida mantiqiy ko&#39;prik yaratadi.</li><li><strong>Referential Integrity (Referensial yaxlitlik):</strong> Foreign Key ustuniga faqat asosiy jadvalda mavjud bo&#39;lgan ID&#39;larni kiritish mumkin! Mavjud bo&#39;lmagan talabaga baho qo&#39;yib yoki mavjud bo&#39;lmagan mijoz nomiga buyurtma yozib bo&#39;lmaydi.</li></ul><h3 id="_5-jadvallararo-munosabatlar-relationships" tabindex="-1">5. Jadvallararo munosabatlar (Relationships) <a class="header-anchor" href="#_5-jadvallararo-munosabatlar-relationships" aria-label="Permalink to &quot;5. Jadvallararo munosabatlar (Relationships)&quot;">​</a></h3><ol><li><strong>One-to-One (1:1 / Birga-bir):</strong> Asosiy jadvaldagi bitta yozuv ikkinchi jadvaldagi faqat bitta yozuvga mos keladi. <ul><li><em>Misol:</em> Bitta fuqaro $\\leftrightarrow$ Bitta xorijga chiqish pasporti.</li></ul></li><li><strong>One-to-Many (1:N / Birga-ko&#39;p):</strong> Asosiy jadvaldagi bitta yozuv ikkinchi jadvaldagi bir nechta yozuvga bog&#39;lanishi mumkin. <ul><li><em>Misol:</em> Bitta mijoz $\\leftrightarrow$ Ko&#39;plab buyurtmalar; Bitta sinf $\\leftrightarrow$ Ko&#39;plab o&#39;quvchilar.</li></ul></li><li><strong>Many-to-Many (M:N / Ko&#39;pga-ko&#39;p):</strong> Birinchi jadvaldagi bitta yozuv ikkinchisidagi ko&#39;p yozuvga, va aksincha mos keladi. <ul><li><em>Misol:</em> Bitta o&#39;quvchi bir nechta fanga qatnashadi, bitta fanda bir nechta o&#39;quvchi o&#39;qiydi.</li><li><em>Amaliy yechim:</em> M:N munosabat relatsion bazalarda to&#39;g&#39;ridan-to&#39;g&#39;ri bog&#39;lanmaydi; u oraliq bog&#39;lovchi jadval (<strong>Junction / Bridge table</strong>) orqali ikkita 1:N munosabatga ajratiladi!</li></ul></li></ol><hr>',14))]),i("div",g,[i("h2",c,[o(l,{name:"file-text"}),a[6]||(a[6]=r(" Amaliy topshiriqlar va yechimlar ",-1)),a[7]||(a[7]=i("a",{class:"header-anchor",href:"#amaliy-topshiriqlar-va-yechimlar","aria-label":'Permalink to "<Icon name="file-text" /> Amaliy topshiriqlar va yechimlar"'},"​",-1))]),a[8]||(a[8]=t('<h3 id="_1-topshiriq-primary-key-aniqlash-oson" tabindex="-1">1-topshiriq. Primary Key aniqlash (oson) <a class="header-anchor" href="#_1-topshiriq-primary-key-aniqlash-oson" aria-label="Permalink to &quot;1-topshiriq. Primary Key aniqlash (oson)&quot;">​</a></h3><p>Maktab kutubxonasi uchun kitoblar jadvali loyihalanmoqda. Quyidagi ustunlardan qaysi biri eng yaxshi Primary Key bo&#39;la oladi va nima uchun? Ustunlar: <code>KitobNomi</code>, <code>Muallif</code>, <code>ISBN_Kodi</code>, <code>NashrYili</code>, <code>SahifalarSoni</code>.</p><p><strong>Yechim:</strong><code>ISBN_Kodi</code> (International Standard Book Number). Chunki kitob nomi va muallifi bir xil bo&#39;lishi mumkin (turli nashriyotlar chop etgan bo&#39;lishi mumkin), nashr yili va sahifalar soni esa ko&#39;plab kitoblarda aynan bir xil bo&#39;ladi. Dunyoda har bir rasmiy kitob nashriga faqat bitta takrorlanmas unikal ISBN kodi beriladi. Shuningdek, sun&#39;iy avtomatik raqamlanuvchi <code>BookID</code> ustunini ham Primary Key qilish mumkin.</p><h3 id="_2-topshiriq-1-n-munosabat-va-foreign-key-joylashtirish-o-rta" tabindex="-1">2-topshiriq. 1:N munosabat va Foreign Key joylashtirish (o&#39;rta) <a class="header-anchor" href="#_2-topshiriq-1-n-munosabat-va-foreign-key-joylashtirish-o-rta" aria-label="Permalink to &quot;2-topshiriq. 1:N munosabat va Foreign Key joylashtirish (o&#39;rta)&quot;">​</a></h3><p>Kompaniyada <code>Kafedralar</code> (Departments) va <code>Xodimlar</code> (Employees) jadvallari mavjud. Bitta kafedrada ko&#39;plab xodimlar ishlaydi, har bir xodim faqat bitta kafedraga tegishli. Ushbu jadvallarning tuzilmasini chizing va Foreign Key qaysi jadvalga qo&#39;yilishini tushuntiring.</p><p><strong>Yechim:</strong></p><ol><li><code>Kafedralar</code> jadvali (Parent/Asosiy jadval): <ul><li><code>KafedraID</code> (Primary Key)</li><li><code>KafedraNomi</code></li></ul></li><li><code>Xodimlar</code> jadvali (Child/Bo&#39;ysunuvchi jadval): <ul><li><code>XodimID</code> (Primary Key)</li><li><code>Ism</code></li><li><code>Lavozim</code></li><li><code>KafedraID</code> (Foreign Key $\\to$ Kafedralar.KafedraID ga bog&#39;lanadi). <em>Qoida:</em> 1:N munosabatda Foreign Key har doim &quot;Ko&#39;p&quot; (Many) tomonidagi jadvalga joylashtiriladi.</li></ul></li></ol><h3 id="_3-topshiriq-ko-pga-ko-p-m-n-munosabatni-loyihalash-qiyin" tabindex="-1">3-topshiriq. Ko&#39;pga-ko&#39;p (M:N) munosabatni loyihalash (qiyin) <a class="header-anchor" href="#_3-topshiriq-ko-pga-ko-p-m-n-munosabatni-loyihalash-qiyin" aria-label="Permalink to &quot;3-topshiriq. Ko&#39;pga-ko&#39;p (M:N) munosabatni loyihalash (qiyin)&quot;">​</a></h3><p>Onlayn do&#39;konda <code>Buyurtmalar</code> (Orders) va <code>Mahsulotlar</code> (Products) o&#39;rtasidagi munosabatni tasavvur qiling. Bitta buyurtmada bir nechta mahsulot bo&#39;lishi mumkin, bitta mahsulot bir nechta buyurtmada sotilishi mumkin. Ushbu Many-to-Many munosabatni relatsion model talablariga mos ravishda oraliq jadval yordamida loyihalang.</p><p><strong>Yechim:</strong> To&#39;g&#39;ridan-to&#39;g&#39;ri M:N bog&#39;lab bo&#39;lmaydi. Shuning uchun uchinchi oraliq jadval — <code>BuyurtmaTafsilotlari</code> (<code>OrderDetails</code> yoki <code>OrderItems</code>) yaratiladi:</p><ol><li><code>Buyurtmalar</code>: <code>OrderID</code> (PK), <code>Sana</code>, <code>MijozID</code></li><li><code>Mahsulotlar</code>: <code>ProductID</code> (PK), <code>MahsulotNomi</code>, <code>Narx</code></li><li><code>BuyurtmaTafsilotlari</code> (Junction Table): <ul><li><code>DetailID</code> (PK)</li><li><code>OrderID</code> (FK $\\to$ Buyurtmalar)</li><li><code>ProductID</code> (FK $\\to$ Mahsulotlar)</li><li><code>Miqdor</code> (Sotib olingan tovarlar soni)</li><li><code>Narx</code> (Aynan o&#39;sha vaqtdagi sotuv narxi) Natijada bitta M:N munosabat ikkita One-to-Many (1:N) munosabatga aylandi!</li></ul></li></ol><hr>',12))]),i("div",v,[i("h2",k,[o(l,{name:"file-text"}),a[9]||(a[9]=r(" Tezkor nazorat savollari ",-1)),a[10]||(a[10]=i("a",{class:"header-anchor",href:"#tezkor-nazorat-savollari","aria-label":'Permalink to "<Icon name="file-text" /> Tezkor nazorat savollari"'},"​",-1))]),a[11]||(a[11]=t("<ol><li>Jadvalda nechta Primary Key ustuni bo&#39;lishi mumkin? <ul><li><em>Javob:</em> Faqat bitta (ammo u bir nechta ustunning birikmasidan iborat kompozit kalit bo&#39;lishi ham mumkin).</li></ul></li><li>Primary Key NULL (bo&#39;sh) qiymat qabul qila oladimi? <ul><li><em>Javob:</em> Yo&#39;q, Primary Key hech qachon NULL bo&#39;lishi mumkin emas.</li></ul></li><li>Foreign Key asosiy jadvalda mavjud bo&#39;lmagan ID qiymatini qabul qilsa nima sodir bo&#39;ladi? <ul><li><em>Javob:</em> Referensial yaxlitlik (Data Integrity) qoidasi buziladi va DBMS xatolik berib, yozuvni qo&#39;shishni rad etadi.</li></ul></li><li>Many-to-Many (M:N) munosabat amalda qanday amalga oshiriladi? <ul><li><em>Javob:</em> Oraliq ko&#39;prik jadvali (Junction table) yordamida ikkita 1:N munosabatga ajratish orqali.</li></ul></li></ol><hr>",2))]),i("div",q,[i("h2",f,[o(l,{name:"house"}),a[12]||(a[12]=r(" Uyga vazifa ",-1)),a[13]||(a[13]=i("a",{class:"header-anchor",href:"#uyga-vazifa","aria-label":'Permalink to "<Icon name="house" /> Uyga vazifa"'},"​",-1))]),a[14]||(a[14]=i("p",null,"O'zingiz qiziqqan soha bo'yicha (masalan, Futbol chempionati, Shifoxona yoki Avtomobil ijarasi xizmati) kamida 3 ta bir-biri bilan bog'langan jadval sxemasini daftaringizda chizing. Har bir jadval uchun:",-1)),a[15]||(a[15]=i("ul",null,[i("li",null,"Jadval nomi va kamida 4 ta ustunini belgilang;"),i("li",null,"Primary Key (PK) ustunini aniqlang;"),i("li",null,"Foreign Key (FK) orqali jadvallarni bir-biriga bog'lang va munosabat turini (1:N yoki M:N) yozing.")],-1))])])}const I=n(m,[["render",p]]);export{P as __pageData,I as default};
